{
  "subtype": "what_if",
  "outcome_variable": "triage_and_scheduling_efficiency",
  "per_column": [
    {
      "name": "estimated_resource_intensity",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Resource intensity of a case is a common cause: it drives how a case might be scheduled/handled and also affects triage/scheduling efficiency. It is a case property, not an actor-set lever, so it is not a clean intervenable treatment; better read as a confounder. Not named in the query."
    },
    {
      "name": "follow_up_required",
      "causal_role": "collider",
      "named_in_query": false,
      "rationale": "Whether follow-up is required is largely an outcome/consequence of the visit and its handling rather than a common cause of an intervenable treatment and efficiency. It is a downstream property, not a confounder or a settable lever."
    },
    {
      "name": "specialist_referral_needed",
      "causal_role": "mediator",
      "named_in_query": false,
      "rationale": "Whether a specialist referral is needed is a clinical property determined by the case; it lies on the pathway between case handling and scheduling outcomes rather than being a pre-treatment common cause. Not a confounder and not an intervenable treatment."
    },
    {
      "name": "has_comorbidity",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Comorbidity is a genuine pre-existing patient trait that plausibly influences both case complexity/handling and triage/scheduling efficiency. It is a valid common-cause confounder, and it is not named in the query. However, it is an immutable patient attribute, not a settable treatment."
    }
  ],
  "treatment_present": false,
  "treatment_columns": [],
  "treatment_intervenable": false,
  "confounders": [
    {
      "name": "estimated_resource_intensity",
      "named_in_query": false,
      "plausibility": 0.5
    },
    {
      "name": "has_comorbidity",
      "named_in_query": false,
      "plausibility": 0.7
    }
  ],
  "confounder_quality": 0.4,
  "rationale": "The query poses an interventional 'how can clinics improve' question, so a valid what-if augmentation needs (a) an intervenable treatment lever (e.g., staffing level, triage protocol, appointment slot policy, walk-in vs booked assignment) and (b) confounders to adjust for. NO added column is an actor-settable lever: estimated_resource_intensity, has_comorbidity are case/patient properties, while follow_up_required and specialist_referral_needed are downstream consequences/mediators. Thus the core requirement -- an intervenable treatment -- is absent, so the interventional claim is not realised. Some columns (has_comorbidity, arguably resource intensity) function as plausible unnamed confounders, showing partial confounder capability, but without a treatment there is nothing to intervene on and the counterfactual effect cannot be set up."
}

